<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form.party-form');if(!form)return;const currency=form.querySelector('select[name="currency_ids[]"]');const rows=Array.from(form.querySelectorAll('[data-currency]'));const add=form.querySelector('#party-add-opening');const date=form.querySelector('#party-opening-date');const hint=form.querySelector('#party-opening-hint');const type=form.querySelector('input[name="type"]').value;function paint(group){const input=group.querySelector('input[name^="opening_directions"],input[name="direction"]');group.querySelectorAll('[data-direction]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.direction===input.value)));}document.querySelectorAll('.balance-direction').forEach(group=>{group.querySelectorAll('[data-direction]').forEach(button=>button.addEventListener('click',()=>{group.querySelector('input').value=button.dataset.direction;paint(group);}));paint(group);});function selected(){return new Set(Array.from(currency.selectedOptions).map(o=>o.value));}function update(){const allowed=selected();rows.forEach(row=>{if(!allowed.has(row.dataset.currency))hide(row);});date.hidden=!rows.some(row=>!row.hidden);hint.hidden=!date.hidden;}function hide(row){row.hidden=true;row.querySelectorAll('input').forEach(el=>{el.disabled=true;if(el.type==='number')el.value='';});}function show(row){row.hidden=false;row.querySelectorAll('input').forEach(el=>el.disabled=false);row.querySelector('input[type=hidden]').value=type==='customer'?'they_owe_us':'we_owe_them';paint(row.querySelector('.balance-direction'));update();}add.addEventListener('click',()=>{const allowed=selected();const row=rows.find(r=>allowed.has(r.dataset.currency)&&r.hidden);if(row){show(row);row.querySelector('input').focus();}else if(!allowed.size){currency.focus();}else{add.blur();}});rows.forEach(row=>{row.querySelector('button').addEventListener('click',()=>{hide(row);update();});if(row.querySelector('input').value){show(row);}});currency.addEventListener('change',update);if(window.jQuery)window.jQuery(currency).on('change',update);update();});</script>
